<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use DI\ContainerBuilder;
use Slim\Psr7\Response;
use Slim\Psr7\Factory\ServerRequestFactory;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepName;

/**
 * Unit tests for step contract DTOs.
 */
final class StepContractUnitTest extends TestCase
{
    private array $serverBackup = [];

    #[Override]
    protected function setUp(): void
    {
        $this->serverBackup = $_SERVER;
        $_SERVER['HTTPS'] = 'on';
        $_SERVER['HTTP_HOST'] = 'example.com';
        $_SERVER['SCRIPT_NAME'] = '/index.php';
    }

    #[Override]
    protected function tearDown(): void
    {
        $_SERVER = $this->serverBackup;
    }

    /**
     * Verifies StepInput preserves all references.
     */
    public function testStepInputStoresContextAndRequest(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid profile',
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        $client = new ClientData('client-123', ['code'], true);
        $authRequest = new AuthenticationRequest(
            client: $client,
            scope: 'openid profile',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );
        $challenges = new ChallengesState(withMfa: true, session: false, username: 'user-1', extra: ['k' => 'v']);

        $input = new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: $challenges,
            body: ['step' => StepName::LOGIN->value],
            request: $request
        );

        $this->assertSame($flow, $input->context);
        $this->assertSame($authRequest, $input->authRequest);
        $this->assertSame($challenges, $input->challenges);
        $this->assertSame(['step' => StepName::LOGIN->value], $input->body);
        $this->assertSame($request, $input->request);
    }

    /**
     * Verifies StepResult factories set expected payloads.
     */
    public function testStepResultFactories(): void
    {
        $response = new Response();
        $authResponse = $this->createMock(PublicLoginAuthResponse::class);
        $challenges = new ChallengesState(withMfa: true, session: false, username: 'user-1');

        $render = StepResult::render($response, $challenges);
        $proceed = StepResult::proceed($authResponse, $challenges);

        $this->assertSame(StepResult::TYPE_RENDER, $render->type);
        $this->assertSame($response, $render->response);
        $this->assertNull($render->authResponse);
        $this->assertSame($challenges, $render->challenges);

        $this->assertSame(StepResult::TYPE_PROCEED, $proceed->type);
        $this->assertSame($authResponse, $proceed->authResponse);
        $this->assertNull($proceed->response);
        $this->assertSame($challenges, $proceed->challenges);
    }

    /**
     * Verifies ChallengesState with* methods are immutable.
     */
    public function testChallengesStateWithMethods(): void
    {
        $state = new ChallengesState();

        $withUser = $state->withUsername('user-1');
        $withMfa = $withUser->withMfa(true);
        $withSession = $withMfa->withSession(true);

        $this->assertNull($state->username);
        $this->assertSame('user-1', $withUser->username);
        $this->assertTrue($withMfa->withMfa);
        $this->assertTrue($withSession->session);
    }

    /**
     * Verifies ChallengesState array serialization with versioning.
     */
    public function testChallengesStateArraySerialization(): void
    {
        $state = new ChallengesState(withMfa: true, session: true, username: 'user-2', extra: ['foo' => 'bar']);
        $data = $state->toArray();

        $this->assertSame(ChallengesState::VERSION, $data['v']);
        $this->assertSame(['foo' => 'bar'], $data['extra']);

        $roundTrip = ChallengesState::fromArray($data);
        $this->assertTrue($roundTrip->withMfa);
        $this->assertTrue($roundTrip->session);
        $this->assertSame('user-2', $roundTrip->username);
        $this->assertSame(['foo' => 'bar'], $roundTrip->extra);
    }
}
